    echo "[+] Creating table `enrollments`...\n";
    $db->exec("DROP TABLE IF EXISTS `enrollments`");
    $db->exec('CREATE TABLE `enrollments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `enrollment_no` varchar(50) DEFAULT NULL,
  `student_no` varchar(50) NOT NULL,
  `student_id` int(11) DEFAULT NULL,
  `application_id` int(11) DEFAULT NULL,
  `school_year_id` int(11) NOT NULL,
  `grade_level_id` int(11) NOT NULL,
  `track_id` int(11) DEFAULT NULL,
  `strand_id` int(11) DEFAULT NULL,
  `section_id` int(11) DEFAULT NULL,
  `lrn` varchar(20) DEFAULT NULL,
  `semester` varchar(30) DEFAULT \'1st Semester\',
  `enrollment_date` date DEFAULT NULL,
  `status` varchar(100) DEFAULT \'Pending Payment\',
  `approved_by` int(11) DEFAULT NULL,
  `enrolled_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=337 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci');

