    echo "[+] Creating table `scholastic_records`...\n";
    $db->exec("DROP TABLE IF EXISTS `scholastic_records`");
    $db->exec('CREATE TABLE `scholastic_records` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `student_id` int(11) NOT NULL,
  `school_year_id` int(11) NOT NULL,
  `grade_level_id` int(11) NOT NULL,
  `strand_id` int(11) DEFAULT NULL,
  `section_id` int(11) DEFAULT NULL,
  `general_average` decimal(5,2) DEFAULT NULL,
  `core_values_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`core_values_json`)),
  `status` enum(\'Promoted\',\'Retained\',\'Conditional\') DEFAULT \'Promoted\',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci');

    echo "[+] Creating table `school_events`...\n";
    $db->exec("DROP TABLE IF EXISTS `school_events`");
    $db->exec('CREATE TABLE `school_events` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `school_year_id` int(11) NOT NULL,
  `created_by` int(11) DEFAULT NULL,
  `title` varchar(200) NOT NULL,
  `description` text DEFAULT NULL,
  `event_category` varchar(50) DEFAULT \'Academic\',
  `category` varchar(50) DEFAULT \'Academic\',
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `event_date` date DEFAULT NULL,
  `start_time` varchar(50) DEFAULT NULL,
  `end_time` varchar(50) DEFAULT NULL,
  `event_time` varchar(50) DEFAULT NULL,
  `location` varchar(150) DEFAULT NULL,
  `target_audience` varchar(100) DEFAULT \'All Students\',
  `is_published` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci');

